:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #253b36;
  background: #f3e8cf;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 24px 16px;
  display: grid;
  place-items: center;
  background-color: #f3e8cf;
  background-image: linear-gradient(45deg, #e6d7b8 25%, transparent 25%), linear-gradient(-45deg, #e6d7b8 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #e6d7b8 75%), linear-gradient(-45deg, transparent 75%, #e6d7b8 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
}

.card {
  width: min(100%, 460px);
  padding: 32px;
  border: 3px solid #253b36;
  border-radius: 8px;
  background: #fffaf0;
  box-shadow: 8px 8px 0 #253b36;
}

.header { text-align: center; }
.pixel-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  display: grid;
  place-items: center;
  border: 3px solid #253b36;
  background: #f2a65a;
  font-size: 28px;
  line-height: 1;
}
.eyebrow { margin: 0; color: #59736a; font-size: 0.8rem; font-weight: 800; letter-spacing: 0.12em; }
h1 { margin: 4px 0; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.1; }
.subtitle { margin: 8px 0 26px; color: #59736a; }

.converter label { display: block; margin-bottom: 8px; font-weight: 750; }
.input-row { display: flex; gap: 10px; }
input, select, button {
  min-height: 52px;
  border: 2px solid #253b36;
  border-radius: 5px;
  font: inherit;
}
input, select { background: #fff; color: #253b36; }
input { width: 42%; padding: 10px 12px; }
select { flex: 1; padding: 10px 12px; }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 3px solid #f2a65a; outline-offset: 3px; }
.hint { margin: 7px 0 16px; color: #59736a; font-size: 0.9rem; }
button { width: 100%; padding: 12px 16px; background: #d96c4b; color: #fffaf0; font-weight: 750; cursor: pointer; transition: background 120ms ease, transform 120ms ease; }
button:hover { background: #bd5237; }
button:active { transform: translateY(2px); }

.results { margin-top: 28px; padding-top: 20px; border-top: 2px dashed #c8b999; }
.results h2 { margin: 0 0 12px; font-size: 1.1rem; }
.result-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.result-list li { display: flex; justify-content: space-between; gap: 12px; padding: 10px 12px; border: 1px solid #d9cfb8; border-radius: 4px; background: #f7f0df; }
.result-list strong { font-variant-numeric: tabular-nums; }
footer { margin-top: 22px; color: #59736a; font-size: 0.88rem; text-align: center; }

@media (max-width: 420px) {
  .card { padding: 24px 20px; }
  body { padding: 20px 14px; }
}

const rates = {
  cups: 240,
  tablespoons: 15,
  teaspoons: 5,
  millilitres: 1
};

const labels = {
  cups: "cups",
  tablespoons: "tablespoons",
  teaspoons: "teaspoons",
  millilitres: "millilitres"
};

const form = document.getElementById("converter");
const amountInput = document.getElementById("amount");
const unitSelect = document.getElementById("unit");
const resultList = document.getElementById("result-list");

function updateResults() {
  const amount = Number(amountInput.value);
  const sourceUnit = unitSelect.value;
  resultList.replaceChildren();

  if (!Number.isFinite(amount) || amount < 0) return;

  for (const [unit, millilitresPerUnit] of Object.entries(rates)) {
    if (unit === sourceUnit) continue;
    const converted = amount * rates[sourceUnit] / millilitresPerUnit;
    const item = document.createElement("li");
    const name = document.createElement("span");
    const value = document.createElement("strong");
    name.textContent = labels[unit];
    value.textContent = `${converted.toFixed(1)} ${unit === "millilitres" ? "ml" : unit}`;
    item.append(name, value);
    resultList.append(item);
  }
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  updateResults();
});
amountInput.addEventListener("input", updateResults);
unitSelect.addEventListener("change", updateResults);
updateResults();
